  select md5('democ:m:manos-listas-multiservicios:0')::uuid, b, (select id from users where phone = '+15705559500'), 'owner', 'José Núñez', 'Yeyo', '{"es":"Dueño y maestro de obra","en":"Owner and handyman"}'::jsonb, 'https://images.pexels.com/photos/11579595/pexels-photo-11579595.jpeg?auto=compress&cs=tinysrgb&w=160', array['es']::text[], '[]'::jsonb, '{"es":"Llegué de Santo Domingo y abrí en 2008. Mi regla es simple: el precio por escrito antes de empezar y nada de sorpresas al final.","en":"I came from Santo Domingo and opened in 2008. My rule is simple: the price in writing before we start and no surprises at the end."}'::jsonb, '{all}'::text[], 'active', true, 0, 2008, true, true
