  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Tienen licencia y seguro?","en":"Are you licensed and insured?"}'::jsonb, '{"es":"Estamos registrados como contratistas de mejoras del hogar (HIC) en Pennsylvania y tenemos seguro de responsabilidad. Pídenos el comprobante cuando quieras.","en":"We are registered as a home improvement contractor (HIC) in Pennsylvania and carry liability insurance. Ask us for proof any time."}'::jsonb, 1);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Atienden emergencias?","en":"Do you handle emergencies?"}'::jsonb, '{"es":"Fuera del horario no, pero si nos escribes por la app te contestamos a primera hora y buscamos el primer espacio.","en":"Not outside business hours, but if you message us in the app we reply first thing and find the first opening."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué zona cubren?","en":"What area do you cover?"}'::jsonb, '{"es":"Vamos a casas en Allentown y los pueblos de alrededor, hasta unas 20 millas. Si estás más lejos, escríbenos y vemos.","en":"We go to homes in Allentown and the surrounding towns, up to about 25 miles. If you are farther, message us and we will see."}'::jsonb, 3);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo se paga?","en":"How do I pay?"}'::jsonb, '{"es":"Con tarjeta en la app al terminar, o en efectivo o tarjeta en persona. Te damos el recibo en el momento.","en":"By card in the app when we finish, or cash or card in person. You get the receipt on the spot."}'::jsonb, 4);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿La visita se cobra?","en":"Is the visit charged?"}'::jsonb, '{"es":"La visita lleva un depósito de $50 que se descuenta del trabajo si lo hacemos con nosotros.","en":"The visit takes a $50 deposit that is credited to the job if we do it."}'::jsonb, 5);
