  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Atienden emergencias de noche y fines de semana?","en":"Do you handle night and weekend emergencies?"}'::jsonb, '{"es":"Sí, las 24 horas. Normalmente llegamos en unos 90 minutos dentro de la zona de Allentown.","en":"Yes, 24 hours. We usually arrive in about 60 minutes inside the Allentown area."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué zona cubren?","en":"What area do you cover?"}'::jsonb, '{"es":"Vamos a casas en Allentown y los pueblos de alrededor, hasta unas 15 millas. Si estás más lejos, escríbenos y vemos.","en":"We go to homes in Allentown and the surrounding towns, up to about 15 miles. If you are farther, message us and we will see."}'::jsonb, 3);
