  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué zona cubren?","en":"What area do you cover?"}'::jsonb, '{"es":"Vamos a casas en Scranton y los pueblos de alrededor, hasta unas 25 millas. Si estás más lejos, escríbenos y vemos.","en":"We go to homes in Scranton and the surrounding towns, up to about 20 miles. If you are farther, message us and we will see."}'::jsonb, 3);
