  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Atienden emergencias de noche y fines de semana?","en":"Do you handle night and weekend emergencies?"}'::jsonb, '{"es":"Sí, las 24 horas. Normalmente llegamos en unos 60 minutos dentro de la zona de Allentown.","en":"Yes, 24 hours. We usually arrive in about 60 minutes inside the Allentown area."}'::jsonb, 2);
