  values (b, 'hzl', 'NEG-HOGAR', array['NEG-HOGAR-03','NEG-HOGAR-28']::text[], 'Destapes Don Lalo', 'active', 'self', (select id from users where phone = '+15705559520'), 'local', '58 E Broad St, Hazleton PA', st_geogfromtext('POINT(-75.974043 40.957263)'), false, 25, '+15705550182', true, array['es','en']::text[], '{"es":"Destape de drenajes y líneas de alcantarilla en Hazleton desde 2015. Contratista registrado en Pennsylvania (HIC), con seguro. Emergencias 24/7. Apartas piezas desde la app y las recoges en 48 horas. También rentamos herramienta por día. Hablamos español e inglés.","en":"Drain and sewer line cleaning in Hazleton since 2015. Pennsylvania-registered contractor (HIC), insured. 24/7 emergencies. Reserve parts in the app and pick them up within 48 hours. We also rent tools by the day. We speak Spanish and English."}'::jsonb, 2015, array['acepta-tarjeta','presupuesto-gratis','con-seguro','plan-de-pagos','con-licencia','emergencia-24-7','productos-a-la-venta','apartado']::text[], array['cita','online','presfree','trabajo','h24','tienda','renta','lic','seguro','y10','finde','galeria','tg']::text[], '{local}', '{"m":"solo","crew":1,"hogar":1,"tarjeta":{"eta":{"es":"Emergencia 24/7 · llega en ~60 min","en":"24/7 emergency · arrives in ~60 min"},"fee":{"es":"Visita $78 · se descuenta","en":"Visit $78 · credited to the job"},"offer":{"es":"Cámara de la línea $149 si destapamos","en":"Camera line inspection $149 if we clear it"}}}'::jsonb, 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20viewBox%3D''0%200%20120%20120''%3E%3Crect%20width%3D''120''%20height%3D''120''%20rx%3D''26''%20fill%3D''%230F4C5C''%2F%3E%3Ctext%20x%3D''60''%20y%3D''76''%20font-family%3D''Arial%2CHelvetica%2Csans-serif''%20font-size%3D''46''%20font-weight%3D''700''%20fill%3D''%23F6E7B0''%20text-anchor%3D''middle''%3EDD%3C%2Ftext%3E%3C%2Fsvg%3E', array['svc','citas','cot','staff','nov','shop','renta']::text[], 'emp', true);
