  select md5('democ:m:destapes-don-lalo:0')::uuid, b, (select id from users where phone = '+15705559520'), 'owner', 'Domingo Guzmán', null, '{"es":"Dueño y técnico de drenajes","en":"Owner and drain technician"}'::jsonb, 'https://images.pexels.com/photos/11579595/pexels-photo-11579595.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Empecé en 2015 con una camioneta y una caja de herramientas. Hoy somos un equipo y seguimos tratando cada casa como si fuera el de mi mamá.","en":"I started in 2015 with a truck and a toolbox. Today we are a team and we still treat every home like it was my mother’s."}'::jsonb, '{all}'::text[], 'active', true, 0, 2015, true, true
