  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Dan el precio antes de empezar?","en":"Do you give the price before starting?"}'::jsonb, '{"es":"Sí. Te mandamos el precio por escrito en la app y solo empezamos cuando lo aceptas. Si aparece algo extra, te pedimos tu OK antes de hacerlo.","en":"Yes. We send the price in writing in the app and only start once you accept it. If something extra comes up, we ask for your OK first."}'::jsonb, 0);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Tienen licencia y seguro?","en":"Are you licensed and insured?"}'::jsonb, '{"es":"Estamos registrados como contratistas de mejoras del hogar (HIC) en Pennsylvania y tenemos seguro de responsabilidad. Pídenos el comprobante cuando quieras.","en":"We are registered as a home improvement contractor (HIC) in Pennsylvania and carry liability insurance. Ask us for proof any time."}'::jsonb, 1);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Atienden emergencias de noche y fines de semana?","en":"Do you handle night and weekend emergencies?"}'::jsonb, '{"es":"Sí, las 24 horas. Normalmente llegamos en unos 90 minutos dentro de la zona de Hazleton.","en":"Yes, 24 hours. We usually arrive in about 45 minutes inside the Hazleton area."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué zona cubren?","en":"What area do you cover?"}'::jsonb, '{"es":"Vamos a casas en Hazleton y los pueblos de alrededor, hasta unas 15 millas. Si estás más lejos, escríbenos y vemos.","en":"We go to homes in Hazleton and the surrounding towns, up to about 15 miles. If you are farther, message us and we will see."}'::jsonb, 3);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo se paga?","en":"How do I pay?"}'::jsonb, '{"es":"Con tarjeta en la app al terminar, o en efectivo o tarjeta en persona. Te damos el recibo en el momento.","en":"By card in the app when we finish, or cash or card in person. You get the receipt on the spot."}'::jsonb, 4);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿La visita se cobra?","en":"Is the visit charged?"}'::jsonb, '{"es":"La visita de diagnóstico se descuenta del trabajo si lo hacemos con nosotros. Los presupuestos son gratis.","en":"The diagnostic visit is credited to the job if we do it. Estimates are free."}'::jsonb, 5);
