  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿La visita se cobra?","en":"Is the visit charged?"}'::jsonb, '{"es":"La visita lleva un depósito de $40 que se descuenta del trabajo si lo hacemos con nosotros.","en":"The visit takes a $40 deposit that is credited to the job if we do it."}'::jsonb, 5);
