  join _c_u u on u.phone = v.ph
on conflict do nothing;
insert into operations (number, kind, city_id, business_id, user_id, member_id, status, status_detail, scheduled_at, duration_min, details, subtotal_cents, deposit_cents, total_cents, pay_mode, pay_status,
    sent_at, answered_at, confirmed_at, done_at, cancelled_at, cancelled_by, cancel_reason, party_size, customer_note, mode, stage, client_key, is_test)
