  from (values ('A-3100094', 'Tanque de expansión', 2, 4900), ('A-3100095', 'Calentador 50 gal · eléctrico (instalado)', 2, 146000), ('A-3100096', 'Calentador 50 gal · eléctrico (instalado)', 2, 146000), ('A-3100097', 'Tanque de expansión', 1, 4900), ('A-3100097', 'Ánodo de magnesio', 1, 2800)) as v(num, es, qty, price)
